    "html": "<div class=\"auth-card\">\n  <h2>Create Password</h2>\n  <div class=\"form-group\">\n    <label for=\"password\">Password</label>\n    <input type=\"password\" id=\"password\" placeholder=\"At least 8 characters\" />\n    <!-- TODO [HTML]: Add <p id=\"password-hint\">Password must contain at least 8 characters</p> -->\n  </div>\n  <div class=\"form-group\">\n    <label for=\"confirm-password\">Confirm Password</label>\n    <input type=\"password\" id=\"confirm-password\" placeholder=\"Re-enter password\" />\n  </div>\n  <div id=\"validation-message\" class=\"message-box\"></div>\n</div>",
    "css": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f1f5f9;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.auth-card {\n  background: #ffffff;\n  padding: 30px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 360px;\n}\nh2 {\n  margin-top: 0;\n  color: #1e293b;\n  font-size: 20px;\n  margin-bottom: 20px;\n}\n.form-group {\n  margin-bottom: 16px;\n  text-align: left;\n}\nlabel {\n  display: block;\n  font-size: 13px;\n  font-weight: 600;\n  color: #475569;\n  margin-bottom: 6px;\n}\ninput {\n  width: 100%;\n  padding: 10px 12px;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  font-size: 14px;\n  outline: none;\n}\n#password-hint {\n  font-size: 12px;\n  color: #64748b;\n  margin: 4px 0 0 0;\n}\n.message-box {\n  min-height: 24px;\n  font-size: 14px;\n  font-weight: 600;\n  margin-top: 8px;\n}\n/* TODO [CSS]: Add styling for .error-text and .success-text */\n.error-text {\n  color: #ef4444;\n}\n.success-text {\n  color: #10b981;\n}",
    "starterJS": "const passwordInput = document.getElementById(\"password\");\nconst confirmPasswordInput = document.getElementById(\"confirm-password\");\nconst validationMessage = document.getElementById(\"validation-message\");\n\n// TODO [JavaScript]:\n// 1. Listen for input events on passwordInput and confirmPasswordInput\n// 2. If password length is less than 8, show error message in red / .error-text\n// 3. If password and confirm do not match, show error in red / .error-text\n// 4. If password >= 8 and both match, display \"Password Matched\" in green / .success-text\n",
    "solutionHTML": "<div class=\"auth-card\">\n  <h2>Create Password</h2>\n  <div class=\"form-group\">\n    <label for=\"password\">Password</label>\n    <input type=\"password\" id=\"password\" placeholder=\"At least 8 characters\" />\n    <p id=\"password-hint\">Password must contain at least 8 characters</p>\n  </div>\n  <div class=\"form-group\">\n    <label for=\"confirm-password\">Confirm Password</label>\n    <input type=\"password\" id=\"confirm-password\" placeholder=\"Re-enter password\" />\n  </div>\n  <div id=\"validation-message\" class=\"message-box\"></div>\n</div>",
    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f1f5f9;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.auth-card {\n  background: #ffffff;\n  padding: 30px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 360px;\n}\nh2 {\n  margin-top: 0;\n  color: #1e293b;\n  font-size: 20px;\n  margin-bottom: 20px;\n}\n.form-group {\n  margin-bottom: 16px;\n  text-align: left;\n}\nlabel {\n  display: block;\n  font-size: 13px;\n  font-weight: 600;\n  color: #475569;\n  margin-bottom: 6px;\n}\ninput {\n  width: 100%;\n  padding: 10px 12px;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  font-size: 14px;\n  outline: none;\n}\n#password-hint {\n  font-size: 12px;\n  color: #64748b;\n  margin: 4px 0 0 0;\n}\n.message-box {\n  min-height: 24px;\n  font-size: 14px;\n  font-weight: 600;\n  margin-top: 8px;\n}\n.error-text {\n  color: #ef4444;\n}\n.success-text {\n  color: #10b981;\n}",
    "solutionJS": "const passwordInput = document.getElementById(\"password\");\nconst confirmPasswordInput = document.getElementById(\"confirm-password\");\nconst validationMessage = document.getElementById(\"validation-message\");\n\nfunction validate() {\n  const pwd = passwordInput.value;\n  const confirm = confirmPasswordInput.value;\n\n  if (pwd.length < 8) {\n    validationMessage.textContent = \"Password must contain at least 8 characters.\";\n    validationMessage.className = \"message-box error-text\";\n    validationMessage.style.color = \"red\";\n  } else if (pwd !== confirm) {\n    validationMessage.textContent = \"Passwords do not match.\";\n    validationMessage.className = \"message-box error-text\";\n    validationMessage.style.color = \"red\";\n  } else {\n    validationMessage.textContent = \"Password Matched\";\n    validationMessage.className = \"message-box success-text\";\n    validationMessage.style.color = \"green\";\n  }\n}\n\npasswordInput.addEventListener(\"input\", validate);\nconfirmPasswordInput.addEventListener(\"input\", validate);",
    "solutionExplanation": "### Solution Breakdown: Password Validation\n\n1. **HTML Additions**: Fulfills all required element additions matching required IDs.\n2. **CSS Styling**: Implements targeted styling rules, colors, and layout properties.\n3. **JavaScript Logic**: Implements core state management, event listeners, and DOM updates."
