    "solutionHTML": "<div class=\"todo-card\">\n  <h2>Daily Tasks</h2>\n  <div class=\"todo-input-group\">\n    <input type=\"text\" id=\"task-input\" placeholder=\"Enter a new task...\" />\n    <button id=\"add-task-btn\" class=\"add-btn\">Add Task</button>\n    <button id=\"clear-all-btn\" class=\"clear-btn\">Clear All</button>\n  </div>\n  <ul id=\"task-list\" class=\"task-list\">\n    <li>Review documentation</li>\n  </ul>\n</div>",
    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f8fafc;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.todo-card {\n  background: #ffffff;\n  padding: 28px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 440px;\n}\nh2 {\n  margin-top: 0;\n  color: #1e293b;\n  font-size: 20px;\n  margin-bottom: 20px;\n}\n.todo-input-group {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 20px;\n}\n#task-input {\n  flex: 1;\n  padding: 10px 14px;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  font-size: 14px;\n  outline: none;\n}\n.add-btn {\n  background: #2563eb;\n  color: white;\n  border: none;\n  padding: 10px 14px;\n  border-radius: 6px;\n  font-weight: 600;\n  cursor: pointer;\n}\n/* TODO [CSS]: Style #clear-all-btn with background: #ef4444 and color: white */\n#clear-all-btn {\n  background: #ef4444;\n  color: white;\n  border: none;\n  padding: 10px 12px;\n  border-radius: 6px;\n  font-weight: 600;\n  cursor: pointer;\n}\n.task-list {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.task-list li {\n  background: #f1f5f9;\n  padding: 10px 14px;\n  border-radius: 6px;\n  font-size: 14px;\n  color: #334155;\n  border-left: 3px solid #2563eb;\n}",
    "solutionJS": "const taskInput = document.getElementById(\"task-input\");\nconst addTaskBtn = document.getElementById(\"add-task-btn\");\nconst taskList = document.getElementById(\"task-list\");\nconst clearAllBtn = document.getElementById(\"clear-all-btn\");\n\nfunction addTask() {\n  const text = taskInput.value.trim();\n  if (!text) return;\n  const li = document.createElement(\"li\");\n  li.textContent = text;\n  taskList.appendChild(li);\n  taskInput.value = \"\";\n}\n\naddTaskBtn.addEventListener(\"click\", addTask);\nif (clearAllBtn) {\n  clearAllBtn.addEventListener(\"click\", () => {\n    taskList.innerHTML = \"\";\n  });\n}",
