    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f8fafc;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.card {\n  background: #ffffff;\n  padding: 32px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 380px;\n}\nh2 {\n  margin-top: 0;\n  color: #0f172a;\n  font-size: 20px;\n  margin-bottom: 20px;\n}\n.input-container {\n  display: flex;\n  gap: 8px;\n}\n#password-input {\n  flex: 1;\n  padding: 10px 14px;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  font-size: 14px;\n  outline: none;\n}\n/* TODO [CSS]: Style #toggle-btn with cursor: pointer and border-radius: 6px */\n#toggle-btn {\n  background: #f1f5f9;\n  border: 1px solid #cbd5e1;\n  color: #334155;\n  padding: 10px 14px;\n  border-radius: 6px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n}",
