    "starterJS": "const celsiusInput = document.getElementById(\"celsius-input\");\nconst convertBtn = document.getElementById(\"convert-btn\");\nconst result = document.getElementById(\"result\");\n// TODO: Select resetTempBtn\n\n// TODO [JavaScript]:\n// 1. Listen for click on convertBtn\n// 2. Convert to Fahrenheit: (Celsius * 9/5) + 32\n// 3. Display error if empty\n// 4. Reset input and result on resetTempBtn click\n",
    "solutionHTML": "<div class=\"converter-card\">\n  <h2>Temperature Converter</h2>\n  <p class=\"subtitle\">Convert Celsius (°C) to Fahrenheit (°F)</p>\n  <div class=\"converter-form\">\n    <div class=\"input-group\">\n      <input type=\"number\" id=\"celsius-input\" placeholder=\"e.g. 25\" />\n      <span class=\"unit\">°C</span>\n    </div>\n    <button id=\"convert-btn\" class=\"convert-btn\">Convert to °F</button>\n    <button id=\"reset-temp-btn\" class=\"reset-btn\">Reset</button>\n  </div>\n  <div id=\"result\" class=\"result-display\">Result will appear here</div>\n</div>",
    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f8fafc;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.converter-card {\n  background: #ffffff;\n  padding: 32px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 360px;\n  text-align: center;\n}\nh2 {\n  margin: 0 0 6px 0;\n  color: #0f172a;\n  font-size: 20px;\n}\n.subtitle {\n  margin: 0 0 20px 0;\n  color: #64748b;\n  font-size: 13px;\n}\n.converter-form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.input-group {\n  display: flex;\n  align-items: center;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  overflow: hidden;\n}\n#celsius-input {\n  flex: 1;\n  padding: 10px 14px;\n  border: none;\n  font-size: 15px;\n  outline: none;\n}\n.unit {\n  background: #f1f5f9;\n  padding: 10px 14px;\n  font-weight: 600;\n  color: #64748b;\n  border-left: 1px solid #cbd5e1;\n}\n.convert-btn {\n  background: #2563eb;\n  color: white;\n  border: none;\n  padding: 12px;\n  border-radius: 6px;\n  font-size: 15px;\n  font-weight: 600;\n  cursor: pointer;\n}\n/* TODO [CSS]: Style #reset-temp-btn with background: #64748b and color: white */\n#reset-temp-btn {\n  background: #64748b;\n  color: white;\n  border: none;\n  padding: 10px;\n  border-radius: 6px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n}\n.result-display {\n  margin-top: 16px;\n  padding: 14px;\n  background: #f8fafc;\n  border-radius: 6px;\n  font-size: 15px;\n  font-weight: 600;\n  color: #1e293b;\n  border: 1px dashed #cbd5e1;\n}",
    "solutionJS": "const celsiusInput = document.getElementById(\"celsius-input\");\nconst convertBtn = document.getElementById(\"convert-btn\");\nconst result = document.getElementById(\"result\");\nconst resetTempBtn = document.getElementById(\"reset-temp-btn\");\n\nconvertBtn.addEventListener(\"click\", () => {\n  const val = celsiusInput.value.trim();\n  if (val === \"\" || isNaN(val)) {\n    result.textContent = \"Please enter a valid temperature\";\n    return;\n  }\n  const c = parseFloat(val);\n  const f = (c * 9) / 5 + 32;\n  result.textContent = `${c}°C = ${f}°F`;\n});\n\nif (resetTempBtn) {\n  resetTempBtn.addEventListener(\"click\", () => {\n    celsiusInput.value = \"\";\n    result.textContent = \"Result will appear here\";\n  });\n}",
