    "solutionHTML": "<div id=\"theme-container\" class=\"theme-wrapper\">\n  <div class=\"theme-card\">\n    <h2 id=\"theme-heading\">Theme Switcher</h2>\n    <p id=\"theme-desc\">Click the button below to toggle between light and dark themes dynamically.</p>\n    <p id=\"theme-status\">Current theme: Light</p>\n    <button id=\"theme-toggle-btn\" class=\"toggle-button\">Dark Mode</button>\n  </div>\n</div>",
    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 0;\n}\n.theme-wrapper {\n  background: #f8fafc;\n  color: #1e293b;\n  min-height: 100vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 24px;\n  transition: background 0.3s, color 0.3s;\n}\n.theme-card {\n  background: #ffffff;\n  padding: 32px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  max-width: 360px;\n  text-align: center;\n}\n#theme-status {\n  font-size: 13px;\n  font-weight: 600;\n  margin: 12px 0;\n  color: #64748b;\n}\n.toggle-button {\n  background: #2563eb;\n  color: white;\n  border: none;\n  padding: 10px 20px;\n  border-radius: 6px;\n  font-weight: 600;\n  cursor: pointer;\n}\n/* TODO [CSS]: Define dark theme */\n.theme-wrapper.dark-theme {\n  background: #0f172a;\n  color: #f8fafc;\n}\n.theme-wrapper.dark-theme .theme-card {\n  background: #1e293b;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);\n}\n.theme-wrapper.dark-theme .toggle-button {\n  background: #38bdf8;\n  color: #0f172a;\n}",
    "solutionJS": "const themeContainer = document.getElementById(\"theme-container\");\nconst themeToggleBtn = document.getElementById(\"theme-toggle-btn\");\nconst themeStatus = document.getElementById(\"theme-status\");\n\nthemeToggleBtn.addEventListener(\"click\", () => {\n  themeContainer.classList.toggle(\"dark-theme\");\n  const isDark = themeContainer.classList.contains(\"dark-theme\");\n  themeToggleBtn.textContent = isDark ? \"Light Mode\" : \"Dark Mode\";\n  if (themeStatus) {\n    themeStatus.textContent = isDark ? \"Current theme: Dark\" : \"Current theme: Light\";\n  }\n});",
